@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');

:root {
  --bg: #070b14;
  --panel: rgba(10, 16, 28, 0.72);
  --panel-strong: rgba(12, 19, 33, 0.92);
  --line: rgba(180, 215, 255, 0.13);
  --line-strong: rgba(190, 225, 255, 0.28);
  --text: #eef5ff;
  --muted: #91a4bd;
  --accent: #5be0ff;
  --accent2: #ffb457;
  --danger: #ff5470;
  --ok: #63f0b0;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --display: 'Space Grotesk', 'Inter', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 100%; height: 100%; overflow: hidden; background: var(--bg); color: var(--text); font-family: var(--font); }
body { user-select: none; -webkit-user-select: none; }
button { font-family: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
canvas#game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.hidden { display: none !important; }
kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 22px; height: 20px; padding: 0 5px; border-radius: 5px; background: rgba(210, 235, 255, .1); border: 1px solid rgba(210, 235, 255, .18); font: 600 10px var(--font); color: #dceaff; }
.glass { background: linear-gradient(150deg, rgba(18, 28, 46, .84), rgba(8, 13, 24, .7)); border: 1px solid var(--line); box-shadow: 0 12px 40px rgba(0, 0, 0, .38), inset 0 1px 0 rgba(255, 255, 255, .05); backdrop-filter: blur(16px) saturate(1.2); }

/* ---------- loading ---------- */
.loading { position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; background: radial-gradient(circle at 50% 45%, #0e1a30, #050810 68%); transition: opacity .8s ease; }
.loading.out { opacity: 0; pointer-events: none; }
.loading-mark { width: 58px; height: 58px; border-radius: 16px; display: grid; place-items: center; font: 700 28px var(--display); background: linear-gradient(135deg, #5be0ff, #2a6dff); color: #041018; box-shadow: 0 0 60px rgba(91, 224, 255, .45); animation: breathe 2.4s ease-in-out infinite; }
@keyframes breathe { 50% { transform: scale(1.06); box-shadow: 0 0 90px rgba(91,224,255,.65); } }
.loading-title { font: 600 22px var(--display); letter-spacing: .35em; }
.loading-bar { width: 240px; height: 3px; background: rgba(255, 255, 255, .1); border-radius: 4px; overflow: hidden; }
.loading-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #5be0ff, #ffb457); animation: load 2s cubic-bezier(.4,0,.2,1) forwards; }
@keyframes load { 0% { width: 0 } 65% { width: 82% } 100% { width: 100% } }
.loading-note { color: var(--muted); font-size: 11px; letter-spacing: .12em; text-transform: uppercase; }

/* ---------- menu ---------- */
.menu { position: fixed; inset: 0; z-index: 60; display: flex; flex-direction: column; padding: 34px 44px; opacity: 0; transition: opacity 1.1s ease; }
.menu.on { opacity: 1; }
.menu-bg { position: absolute; inset: 0; background: radial-gradient(110% 80% at 78% 20%, rgba(6, 12, 24, .05), rgba(4, 7, 14, .62) 55%, rgba(3, 5, 10, .94) 100%), linear-gradient(90deg, rgba(4,7,14,.86) 0%, rgba(4,7,14,.45) 40%, transparent 70%), linear-gradient(0deg, rgba(3,5,10,.9), transparent 40%); pointer-events: none; }
.menu-top, .menu-body, .menu-foot { position: relative; z-index: 1; }
.menu-top { display: flex; justify-content: space-between; align-items: center; }
.brand { display: flex; align-items: center; gap: 12px; font: 600 15px var(--display); letter-spacing: .28em; }
.brand-mark { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; font-weight: 800; letter-spacing: 0; background: linear-gradient(135deg, #5be0ff, #2a6dff); color: #041018; }
.menu-links { display: flex; gap: 12px; font-size: 10px; letter-spacing: .18em; color: var(--muted); }
.menu-body { flex: 1; display: flex; flex-direction: column; justify-content: center; max-width: 660px; padding-left: 1vw; }
.menu-kicker { font-size: 10px; letter-spacing: .34em; color: var(--accent); margin-bottom: 20px; text-transform: uppercase; }
.menu-body h1 { font: 600 clamp(44px, 5.2vw, 76px)/.98 var(--display); letter-spacing: -.045em; text-shadow: 0 10px 60px rgba(0,0,0,.5); }
.menu-body h1 em { font-style: normal; color: transparent; background: linear-gradient(100deg, #9ee9ff, #5be0ff 42%, #ffc27a); -webkit-background-clip: text; background-clip: text; }
.menu-copy { max-width: 480px; margin-top: 22px; color: #b8c7da; font-size: 14px; line-height: 1.7; font-weight: 300; }
.menu-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 34px; max-width: 590px; }
.btn { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 3px; padding: 14px 20px; border-radius: 12px; transition: .22s ease; text-align: left; min-width: 170px; }
.btn span { font: 600 14px var(--display); letter-spacing: .02em; }
.btn small { font-size: 9.5px; letter-spacing: .1em; color: var(--muted); text-transform: uppercase; }
.btn.primary { background: linear-gradient(135deg, #8ceaff, #4ac8f2 50%, #3b8cff); color: #031018; box-shadow: 0 10px 40px rgba(70, 190, 255, .3), inset 0 1px 0 rgba(255,255,255,.55); }
.btn.primary small { color: rgba(3, 20, 30, .62); }
.btn.primary:hover { transform: translateY(-2px); box-shadow: 0 16px 50px rgba(70, 190, 255, .45); }
.btn.ghost { border: 1px solid var(--line-strong); background: rgba(12, 20, 35, .55); backdrop-filter: blur(12px); }
.btn.ghost:hover { background: rgba(28, 44, 70, .7); border-color: rgba(160, 220, 255, .45); transform: translateY(-2px); }
.btn.ghost:disabled { opacity: .42; pointer-events: none; }
.menu-stats { display: flex; gap: 40px; margin-top: 46px; }
.menu-stats div { display: flex; flex-direction: column; gap: 4px; }
.menu-stats b { font: 500 22px var(--display); color: #fff; }
.menu-stats span { font-size: 9px; letter-spacing: .18em; color: var(--muted); text-transform: uppercase; }
.menu-foot { display: flex; justify-content: space-between; color: rgba(170, 190, 215, .55); font-size: 9.5px; letter-spacing: .13em; text-transform: uppercase; }

/* ---------- HUD ---------- */
.hud { position: fixed; inset: 0; z-index: 20; pointer-events: none; }
.hud > * { pointer-events: none; }
.hud .sys-btn, .hud .chip, .hud .controls-hint { pointer-events: auto; }
.hud-top-left { position: absolute; top: 22px; left: 22px; display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.minimap-panel { position: relative; width: 188px; height: 188px; border-radius: 50%; overflow: hidden; padding: 5px; }
.minimap-panel::after { content: ''; position: absolute; inset: 5px; border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(255,255,255,.14), inset 0 0 40px rgba(0,0,0,.5); pointer-events: none; }
#minimap { width: 100%; height: 100%; border-radius: 50%; display: block; }
.minimap-north { position: absolute; top: 8px; left: 50%; transform: translateX(-50%); font: 600 9px var(--display); color: rgba(220,240,255,.7); z-index: 2; }
.district-label { position: absolute; bottom: 22px; left: 50%; transform: translateX(-50%); font: 600 8.5px var(--display); letter-spacing: .2em; white-space: nowrap; color: #d8e9ff; text-shadow: 0 2px 8px #000; z-index: 2; }
.status-row { display: flex; gap: 8px; }
.chip { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px; border-radius: 9px; background: rgba(8, 14, 25, .75); border: 1px solid var(--line); backdrop-filter: blur(10px); font: 500 13px var(--display); }
.chip.money .icon { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; background: rgba(255, 190, 90, .14); color: var(--accent2); font-size: 11px; }
.chip.wanted { color: #ffcf7a; letter-spacing: .1em; }
.chip.wanted.alert { border-color: rgba(255, 84, 112, .55); box-shadow: 0 0 24px rgba(255, 84, 112, .25); animation: pulse 1.1s infinite; }
@keyframes pulse { 50% { box-shadow: 0 0 8px rgba(255,84,112,.2); } }
.notification-stack { display: flex; flex-direction: column; gap: 6px; max-width: 300px; }
.notification { padding: 8px 12px; border-radius: 8px; background: rgba(8, 14, 25, .8); border-left: 2px solid var(--accent); backdrop-filter: blur(10px); font-size: 11px; color: #d8e8ff; animation: notif .3s ease; }
.notification.good { border-left-color: var(--ok); }
.notification.bad { border-left-color: var(--danger); }
.notification.warn { border-left-color: var(--accent2); }
@keyframes notif { from { opacity: 0; transform: translateX(-8px); } }

.hud-top-right { position: absolute; top: 22px; right: 22px; display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
.clock-panel { width: 166px; padding: 12px 14px; border-radius: 11px; }
.clock-panel .time { font: 500 26px var(--display); letter-spacing: -.02em; }
.clock-panel .sub { font-size: 9px; letter-spacing: .1em; color: var(--muted); text-transform: uppercase; margin-top: 1px; }
.daybar { height: 3px; background: rgba(255,255,255,.09); border-radius: 3px; margin-top: 9px; overflow: hidden; }
.daybar i { display: block; height: 100%; width: 30%; background: linear-gradient(90deg, #5be0ff, #ffb457); }
.sys-buttons { display: flex; gap: 6px; }
