        add(new THREE.BoxGeometry(.6, .8, .3), new THREE.MeshStandardMaterial({ color: 0xc9a44a, roughness: .5, metalness: .4 }), -7 + i * 2.5, 1.6, -6.2);
      }
      this.makeClerk(g, 4, -6.6, 0, 0x7b2f2a);
