237:   buildBlocks(rng) {
238:     const sidewalkGeo = new THREE.PlaneGeometry(SPACING - ROAD_W, SPACING - ROAD_W);
239:     sidewalkGeo.rotateX(-Math.PI / 2);
240:     const swMat = this.mats.sidewalk.clone();
241:     swMat.map = this.mats.sidewalk.map.clone();
242:     swMat.map.repeat.set(12, 12);
243:     swMat.map.needsUpdate = true;
244:     this.sidewalkMat = swMat;
245:     this.sidewalkMesh = new THREE.InstancedMesh(sidewalkGeo, swMat, 64);
246:     const tmp = new THREE.Object3D();
247:     let swIndex = 0;
248: 
249:     const lotMatConcrete = this.mats.lot.clone();
250:     lotMatConcrete.map = this.mats.lot.map.clone(); lotMatConcrete.map.repeat.set(9, 9);
251:     const lotMatGrass = this.mats.grass.clone();
252:     lotMatGrass.map = this.mats.grass.map.clone(); lotMatGrass.map.repeat.set(9, 9);
253:     const lots = { concrete: [], grass: [] };
254: 
255:     const curbGeo = new THREE.BoxGeometry(68, 0.16, 0.28);
256:     const curbs = [];
257: 
258:     for (let bi = 0; bi < 8; bi++) {
259:       for (let bj = 0; bj < 8; bj++) {
260:         const x = BLOCK_CENTER(bi), z = BLOCK_CENTER(bj);
261:         const special = SPECIAL[`${bi},${bj}`] || null;
262:         const district = this.districtForBlock(bi, bj, special);
263:         const block = { bi, bj, x, z, district, special };
264:         this.blocks.push(block);
265: 
266:         tmp.position.set(x, 0.1, z); tmp.rotation.set(0, 0, 0); tmp.scale.set(1, 1, 1); tmp.updateMatrix();
267:         this.sidewalkMesh.setMatrixAt(swIndex++, tmp.matrix);
268: 
269:         const isGreen = ['suburb', 'park', 'residential'].includes(district) || special === 'park';
270:         (isGreen ? lots.grass : lots.concrete).push([x, z]);
271:         curbs.push([x, z - 34, 0], [x, z + 34, 0], [x - 34, z, Math.PI / 2], [x + 34, z, Math.PI / 2]);
272: 
273:         this.buildBlockContent(block, rng);
274:       }
275:     }
276:     this.root.add(this.sidewalkMesh);
277:     this.lotMeshes = [];
278:     for (const [key, arr] of Object.entries(lots)) {
279:       if (!arr.length) continue;
280:       const geo = new THREE.PlaneGeometry(68, 68); geo.rotateX(-Math.PI / 2);
281:       const mesh = new THREE.InstancedMesh(geo, key === 'grass' ? lotMatGrass : lotMatConcrete, arr.length);
282:       arr.forEach(([x, z], i) => { tmp.position.set(x, 0.15, z); tmp.updateMatrix(); mesh.setMatrixAt(i, tmp.matrix); });
283:       mesh.receiveShadow = true;
284:       this.root.add(mesh); this.lotMeshes.push(mesh);
285:     }
286:     const curbMat = new THREE.MeshStandardMaterial({ color: 0x8f8f8a, roughness: 0.95 });
287:     const curbMesh = new THREE.InstancedMesh(curbGeo, curbMat, curbs.length);
288:     curbs.forEach(([x, z, r], i) => {
289:       tmp.position.set(x, 0.18, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
290:       curbMesh.setMatrixAt(i, tmp.matrix);
291:     });
292:     this.root.add(curbMesh);
293:   }
