295:   districtForBlock(bi, bj, special) {
296:     if (special === 'park') return 'park';
297:     if (special === 'suburb') return 'suburb';
298:     if (special === 'industrial') return 'industrial';
299:     if (special === 'airport') return 'airport';
300:     if (bj <= 1) return 'industrial';
301:     if (bi >= 6 && bj >= 2 && bj <= 5) return 'suburb';
302:     if (bj >= 6) return 'waterfront';
303:     if (bi <= 2 && bj >= 3) return 'residential';
304:     if (bi >= 3 && bi <= 5 && bj >= 2 && bj <= 5) return 'downtown';
305:     return 'midtown';
306:   }
