332:   facadeGeometry(w, h, d) {
333:     const geo = new THREE.BoxGeometry(w, h, d);
334:     const uv = geo.attributes.uv;
335:     const reps = [
336:       [d, h], [d, h], [w, d], [w, d], [w, h], [w, h],
337:     ];
338:     for (let f = 0; f < 6; f++) {
339:       const rx = reps[f][0] / 12, ry = reps[f][1] / 13;
340:       for (let k = 0; k < 4; k++) {
341:         const idx = f * 4 + k;
342:         uv.setXY(idx, uv.getX(idx) * rx, uv.getY(idx) * ry);
343:       }
344:     }
345:     uv.needsUpdate = true;
346:     return geo;
347:   }
