395:   buildDowntown(block, rng) {
396:     const { x, z } = block;
397:     const w = 34 + rng() * 26, d = 34 + rng() * 26;
398:     const h = 58 + rng() * 120;
399:     const offX = (rng() - .5) * (66 - w), offZ = (rng() - .5) * (66 - d);
400:     const bx = x + offX, bz = z + offZ;
401:     const variant = Math.floor(rng() * 4);
402:     const { mesh } = this.addBuilding(bx, bz, w, d, h, 'downtown', variant, { roofMat: this.roofMatDark });
403:     // podium
404:     const podH = 7 + rng() * 9;
405:     if (rng() > 0.35) {
406:       const pod = this.addBuilding(bx, bz, w + 8, d + 8, podH, 'downtown', (variant + 1) % 4, { roofMat: this.roofMat });
407:       pod.mesh.castShadow = true;
408:     }
409:     // setbacks
410:     if (h > 100 && rng() > .35) {
411:       const h2 = h * (0.18 + rng() * .12);
412:       this.addBuilding(bx, bz, w * .72, d * .72, h2, 'downtown', (variant + 2) % 4, { base: h, roofMat: this.roofMatDark });
413:     }
414:     this.addRoofDetails(bx, bz, w, d, h + 0.2, rng, h > 70 ? 'tower' : 'normal');
415:     // facade fins for glass towers
416:     if (variant < 2) {
417:       const finMat = new THREE.MeshStandardMaterial({ color: 0x9fb3c4, roughness: .4, metalness: .6 });
418:       for (let i = -2; i <= 2; i++) {
419:         const fin = new THREE.Mesh(new THREE.BoxGeometry(0.28, h * .94, 0.5), finMat);
420:         fin.position.set(bx + i * w / 6, h / 2 + .2, bz + d / 2 + 0.3);
421:         this.root.add(fin);
422:       }
423:     }
424:     if (h > 125) {
425:       const sign = new THREE.Mesh(new THREE.PlaneGeometry(18, 5), new THREE.MeshBasicMaterial({ map: billboardTexture('NOVA', 'ABOVE ALL', '#0a2d4d', '#1b6d91'), transparent: false }));
426:       sign.position.set(bx, h * .75, bz + d / 2 + 0.3);
427:       this.root.add(sign);
428:     }
429:   }
