502:     dock.position.set(bx, .85, bz + d / 2 + 1.6); dock.castShadow = true; this.root.add(dock);
503:     // containers
504:     const colors = [0x8e3b32, 0x2e5f7a, 0x7c6a2e, 0x356b4a, 0x7a4a32];
505:     for (let i = 0; i < 4 + Math.floor(rng() * 5); i++) {
506:       const cw = 6, ch = 2.6, cd = 2.5;
507:       const cont = new THREE.Mesh(new THREE.BoxGeometry(cw, ch, cd), new THREE.MeshStandardMaterial({ color: pick(colors), roughness: .8, metalness: .3 }));
508:       cont.position.set(x - 24 + rng() * 48, .6 + (rng() > .8 ? ch : 0), z + 24 + rng() * 8);
