688:   buildSignals() {
689:     const nodes = [];
690:     for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
691:       const central = Math.abs(i - 4) <= 3 && Math.abs(j - 4) <= 3;
692:       nodes.push({ i, j, x: NODE_POS(i), z: NODE_POS(j), hasLights: central });
693:     }
694:     this.nodes = nodes;
695:     this.nodeGrid = [];
696:     for (let i = 0; i < GRID; i++) { this.nodeGrid[i] = []; for (let j = 0; j < GRID; j++) this.nodeGrid[i][j] = nodes.find(n => n.i === i && n.j === j); }
697: 
698:     const poleGeo = new THREE.CylinderGeometry(.12, .16, 4.8, 6);
699:     const poleMat = new THREE.MeshStandardMaterial({ color: 0x3a3f44, roughness: .8, metalness: .4 });
700:     const lampGeo = new THREE.SphereGeometry(.19, 8, 6);
701:     const lampMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
702:     const lampPositions = [];
703:     const poles = [];
704:     const armGeo = new THREE.BoxGeometry(2.2, .12, .12);
705:     const arms = [];
706:     this.signalLampData = [];
707:     for (const n of nodes) {
708:       if (!n.hasLights) continue;
709:       const corners = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
710:       for (const [sx, sz] of corners) {
711:         const px = n.x + sx * (HALF_ROAD + 1.3), pz = n.z + sz * (HALF_ROAD + 1.3);
712:         poles.push([px, 2.4, pz]);
713:         arms.push([px + (sx > 0 ? -1 : 1) * 1.1, 4.35, pz, sx > 0 ? 0 : Math.PI]);
714:         for (let k = 0; k < 3; k++) {
715:           const ly = 4.75 - k * .34;
716:           lampPositions.push([px + (sx > 0 ? -1.05 : 1.05), ly, pz]);
717:           this.signalLampData.push({ node: n, axis: sz === 0 ? 'x' : 'z', slot: k, index: lampPositions.length - 1 });
718:         }
719:       }
720:     }
721:     const poleMesh = new THREE.InstancedMesh(poleGeo, poleMat, poles.length);
722:     const tmp = new THREE.Object3D();
723:     poles.forEach(([x, y, z], i) => { tmp.position.set(x, y, z); tmp.updateMatrix(); poleMesh.setMatrixAt(i, tmp.matrix); });
724:     this.root.add(poleMesh);
725:     const armMesh = new THREE.InstancedMesh(armGeo, poleMat, arms.length);
726:     arms.forEach(([x, y, z, r], i) => { tmp.position.set(x, y, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix(); armMesh.setMatrixAt(i, tmp.matrix); });
727:     this.root.add(armMesh);
728:     this.signalLampMesh = new THREE.InstancedMesh(lampGeo, lampMat, lampPositions.length);
729:     this.signalLampMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(lampPositions.length * 3), 3);
730:     lampPositions.forEach(([x, y, z], i) => {
731:       tmp.position.set(x, y, z); tmp.rotation.set(0, 0, 0); tmp.updateMatrix();
732:       this.signalLampMesh.setMatrixAt(i, tmp.matrix);
733:       this.signalLampMesh.setColorAt(i, new THREE.Color(0x111111));
734:     });
735:     this.root.add(this.signalLampMesh);
736:     this.signalNodes = nodes;
737:   }
