755:   updateSignals(elapsed) {
756:     const colors = { red: new THREE.Color(0xff2b3e), yellow: new THREE.Color(0xffb12b), green: new THREE.Color(0x2bff9a), off: new THREE.Color(0x101316) };
757:     for (const data of this.signalLampData) {
758:       const state = this.signalState(data.node, data.axis, elapsed);
759:       const active = state === 'red' ? 0 : state === 'yellow' ? 1 : 2;
760:       let c;
761:       if (data.slot === active) c = colors[state];
762:       else c = colors.off;
763:       this.signalLampMesh.setColorAt(data.index, c);
764:     }
765:     this.signalLampMesh.instanceColor.needsUpdate = true;
766:   }
