817:   updateLighting(hour, weather, dt) {
818:     this.hour = hour;
819:     const day = Math.max(0, Math.sin((hour - 6) / 24 * TAU));
820:     const night = clamp(1 - Math.max(0, Math.sin((hour - 5.5) / 24 * TAU)) * 2.2, 0, 1);
821:     this.night = night;
822:     this.weather = weather;
823:     const storm = weather === 'storm' ? 1 : weather === 'rain' ? .7 : weather === 'snow' ? .55 : 0;
824:     const dim = 1 - storm * .35;
825:     if (this.sun) {
826:       const sunAngle = (hour / 24) * TAU - Math.PI / 2;
827:       this.sun.position.set(Math.cos(sunAngle) * 700, Math.sin(sunAngle) * 700, 260);
828:       this.sun.intensity = clamp(Math.sin((hour - 5.8) / 12.4 * Math.PI) * 2.6, 0, 2.6) * dim;
829:       this.sun.color.setHSL(0.09 + day * .02, .45, .55 + day * .25);
830:     }
831:     this.hemi.intensity = lerp(0.2, 0.7, day) * dim;
832:     this.ambient.intensity = lerp(0.18, 0.32, day);
833:     const glow = night * 1.9 + (storm > 0 ? .15 : 0);
834:     for (const m of this.facadeMaterials) m.emissiveIntensity = 0.015 + glow * 0.95;
835:     if (this.lampGlow) {
836:       this.lampGlow.material.opacity = 0.22 + night * 0.78;
837:       this.lampGlow.material.size = 6 + night * 2;
838:     }
839:     if (this.crownMat) this.crownMat.emissiveIntensity = .2 + night * 2.4;
840:     if (this.sky) {
841:       this.sky.material.uniforms.night.value = night;
842:       this.sky.material.uniforms.storm.value = storm;
843:       this.sky.material.uniforms.sunDir.value.copy(this.sun.position).normalize();
844:     }
845:     if (this.stars) this.stars.material.opacity = clamp(night * 1.1 - .15, 0, .95);
846:     if (this.water) this.water.material.uniforms.night.value = night;
847:     if (this.moon) this.moon.material.opacity = night * .95;
848:     if (this.cloudSpriteMat) this.cloudSpriteMat.color.setScalar(lerp(1.1, .18, night) * (1 - storm * .25));
849:     document.body.dataset.night = night > .55 ? '1' : '0';
850:   }
