880:   updateFactorySmoke(dt, elapsed) {
881:     if (!this.factorySmokePos || !this.smokeParticles) return;
882:     const p = this.smokeParticles;
883:     p.userData.t = (p.userData.t || 0) + dt;
884:     const pos = p.geometry.attributes.position;
885:     for (let i = 0; i < pos.count; i++) {
886:       let y = pos.getY(i) + dt * (2.2 + (i % 5) * .3);
887:       let x = pos.getX(i) + dt * .55;
888:       let z = pos.getZ(i) + Math.sin(elapsed * .6 + i) * dt * .2;
889:       if (y > 50) { y = 0; x = this.factorySmokePos.x + (Math.random() - .5) * 2; z = this.factorySmokePos.z + (Math.random() - .5) * 2; }
890:       pos.setXYZ(i, x, y, z);
891:     }
892:     pos.needsUpdate = true;
893:   }
894: 
