88:   initTraffic() {
89:     let node = this.game.city.nearestNode(this.pos.x, this.pos.z);
90:     let dir = pick(AXES);
91:     let next = this.getNeighbor(node, dir);
92:     let guard = 0;
93:     while (!next && guard++ < 8) { dir = pick(AXES); next = this.getNeighbor(node, dir); }
94:     if (!next) { this.mode = 'parked'; return; }
95:     this.traffic = {
96:       node, next, dir, t: rand(2, 60), lane: 3.9, cruise: this.type === 'bus' || this.type === 'truck' ? rand(8, 10) : rand(10, 14),
97:       turnTimer: 0, stopTimer: 0,
98:     };
99:     const p = this.lanePoint(this.traffic);
100:     this.pos.x = p.x; this.pos.z = p.z;
101:     this.heading = Math.atan2(dir[0], dir[1]);
102:     this.group.rotation.y = this.heading;
103:     this.mode = 'traffic';
104:   }
105: 
106:   getNeighbor(node, dir) {
107:     const i = node.i + dir[0], j = node.j + dir[1];
108:     if (i < 0 || i >= 9 || j < 0 || j >= 9) return null;
109:     return this.game.city.nodeGrid[i][j];
110:   }
111: 
112:   lanePoint(tr, ahead = 0) {
113:     const nx = tr.node.x + tr.dir[0] * (tr.t + ahead);
114:     const nz = tr.node.z + tr.dir[1] * (tr.t + ahead);
115:     const rx = -tr.dir[1], rz = tr.dir[0];
116:     return { x: nx + rx * tr.lane, z: nz + rz * tr.lane };
117:   }
118: 
119:   chooseNext(tr) {
120:     const options = [];
121:     const back = [-tr.dir[0], -tr.dir[1]];
122:     for (const d of AXES) {
123:       if (d[0] === back[0] && d[1] === back[1]) continue;
124:       if (this.getNeighbor(tr.next, d)) options.push(d);
125:     }
126:     if (!options.length) return [-tr.dir[0], -tr.dir[1]];
127:     // prefer straight
128:     const straight = options.filter(d => d[0] === tr.dir[0] && d[1] === tr.dir[1]);
129:     if (straight.length && Math.random() < .55) return straight[0];
130:     return pick(options);
131:   }
132: 
133:   updateTraffic(dt, elapsed, night, weather) {
134:     const tr = this.traffic;
135:     if (!tr) return;
136:     if (this.knockTimer > 0) {
137:       this.knockTimer -= dt;
138:       this.pos.x += this.knock.x * dt;
139:       this.pos.z += this.knock.y * dt;
140:       this.knock.multiplyScalar(1 - dt * 4);
141:     }
142:     const segLen = 96;
143:     // signal ahead
144:     const axis = tr.dir[0] !== 0 ? 'x' : 'z';
145:     const distToNode = segLen - tr.t;
146:     let targetSpeed = tr.cruise;
147:     let stop = false;
148:     if (distToNode < 25) {
149:       const state = this.game.city.signalState(tr.next, axis, elapsed);
150:       if (state === 'red' || (state === 'yellow' && distToNode > 8)) {
151:         if (distToNode < 19) stop = true;
152:       }
153:     }
154:     // forward obstacle: traffic and player vehicles
155:     if (!stop) {
156:       const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
157:       for (const other of this.game.vehicles.vehicles) {
158:         if (other === this) continue;
159:         const dx = other.pos.x - this.pos.x, dz = other.pos.z - this.pos.z;
160:         const d = Math.hypot(dx, dz);
161:         if (d < (other.cfg.len + this.cfg.len) * .5 + 4 && d > 0.01) {
162:           const dot = (dx * fx + dz * fz) / d;
163:           if (dot > .7) { stop = true; break; }
164:         }
165:       }
166:       // pedestrians in front
167:       const ped = this.game.npcs?.anyInFront(this.pos.x, this.pos.z, this.heading, 8);
168:       if (ped) stop = true;
169:     }
170:     if (stop) targetSpeed = 0;
171:     if (this.health < 15) targetSpeed = 0;
172:     const accel = stop ? this.cfg.brake * .8 : this.cfg.accel * .55;
173:     this.speed = this.speed < targetSpeed ? Math.min(targetSpeed, this.speed + accel * dt) : Math.max(targetSpeed, this.speed - this.cfg.brake * dt);
174:     this.brakeOn = stop && this.speed > .1;
175:     // steering
176:     const p = this.lanePoint(tr, 10);
177:     const dx = p.x - this.pos.x, dz = p.z - this.pos.z;
178:     const desired = Math.atan2(dx, dz);
179:     let diff = normAngle(desired - this.heading);
180:     const turnRate = clamp(this.speed * .35, 0, 2.2);
181:     this.heading = normAngle(this.heading + clamp(diff, -turnRate * dt, turnRate * dt));
182:     // move
183:     const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
184:     this.pos.x += fx * this.speed * dt;
185:     this.pos.z += fz * this.speed * dt;
186:     this.group.rotation.y = this.heading;
187:     tr.t += this.speed * dt;
188:     // lane correction
189:     const lp = this.lanePoint(tr, 0);
190:     this.pos.x += (lp.x - this.pos.x) * Math.min(1, dt * 1.5);
191:     this.pos.z += (lp.z - this.pos.z) * Math.min(1, dt * 1.5);
192:     if (tr.t >= segLen) {
193:       tr.t -= segLen;
194:       tr.node = tr.next;
195:       tr.dir = this.chooseNext(tr);
196:       tr.next = this.getNeighbor(tr.node, tr.dir);
197:       if (!tr.next) { tr.node = this.game.city.nearestNode(this.pos.x, this.pos.z); tr.dir = pick(AXES); tr.next = this.getNeighbor(tr.node, tr.dir); }
198:     }
199:     // visuals
200:     this.animateWheels(dt);
201:     this.speedKmh = this.speed * 3.6;
202:     if (this.lightsOn !== (night > .4 || weather !== 'clear')) { this.lightsOn = night > .4 || weather !== 'clear'; }
203:     setLightState(this.headMats, this.brakeMats, this.turnMats, { lightsOn: this.lightsOn, braking: this.brakeOn || this.speed < .2 });
204:     if (this.serviceLights) {
205:       const on = Math.floor(elapsed * 5) % 2 === 0;
206:       this.serviceLights.redM.color.setHex(on ? 0xff2020 : 0x300808);
207:       this.serviceLights.blueM.color.setHex(on ? 0x0a0a30 : 0x2a5bff);
208:       this.serviceLights.light.color.setHex(on ? 0xff2020 : 0x2a5bff);
209:       this.serviceLights.light.intensity = on ? 2.6 : 2.2;
210:     }
211:   }
212: 
213:   updatePlayer(dt, controls, weather, elapsed, night) {
214:     this.isPlayer = true;
215:     if (this.isAir) return this.updateHelicopter(dt, controls, night);
216:     if (this.isBoat) return this.updateBoat(dt, controls, weather, night);
217:     const cfg = this.cfg;
218:     const f = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
219:     const r = new THREE.Vector2(-f.y, f.x);
220:     let vf = this.velocity.dot(f);
221:     let vr = this.velocity.dot(r);
222:     const damageFactor = clamp(1 - (100 - this.health) / 150, .35, 1);
223:     const hasFuel = this.fuel > 0.1;
224:     const engine = this.engineOn && hasFuel && this.health > 6;
225:     this.throttle = controls.throttle || 0;
226:     this.brakeInput = controls.brake || 0;
227:     this.handbrake = !!controls.handbrake;
228:     const offroad = !this.game.city.isOnRoad(this.pos.x, this.pos.z);
229:     const wet = weather === 'rain' || weather === 'storm';
230:     const maxSpeed = cfg.maxSpeed * damageFactor * (offroad ? .62 : 1) * (wet ? .86 : 1);
231:     // reverse handling
232:     if (this.brakeInput > 0 && vf <= .4) {
233:       if (engine) vf -= cfg.accel * .45 * dt * damageFactor;
234:     } else if (this.brakeInput > 0) {
235:       vf -= cfg.brake * this.brakeInput * dt;
236:     }
237:     if (this.throttle > 0 && engine) {
238:       const power = cfg.accel * (1 - clamp(Math.abs(vf) / maxSpeed, 0, 1) * .72);
239:       vf += power * this.throttle * dt * damageFactor;
240:     }
241:     vf = clamp(vf, -maxSpeed * .35, maxSpeed);
242:     // drag + rolling
243:     vf *= 1 - dt * (offroad ? 1.2 : .22);
244:     vf -= Math.sign(vf) * Math.min(Math.abs(vf), (offroad ? 4.5 : 0.8) * dt);
245:     // lateral grip
246:     let grip = cfg.grip * (wet ? .52 : 1) * (offroad ? .55 : 1);
247:     if (this.handbrake) grip *= .16;
248:     if (this.health < 40) grip *= .86;
249:     vr *= Math.exp(-grip * dt);
250:     // steering
251:     const steerTarget = controls.steer || 0;
252:     this.steer = lerp(this.steer, steerTarget, clamp(dt * 8, 0, 1));
253:     const speedFactor = clamp(Math.abs(vf) / 7, 0, 1);
254:     const turnBoost = this.handbrake ? 1.45 : 1;
255:     const turnRate = 1.5 * speedFactor * (1 - clamp(Math.abs(vf) / cfg.maxSpeed, 0, 1) * .38) * turnBoost;
256:     this.heading = normAngle(this.heading + this.steer * turnRate * dt * (vf < 0 ? -1 : 1));
257:     // wet slide adds lateral velocity through the turn
258:     if (wet || this.handbrake) {
259:       vr += this.steer * vf * (wet ? .09 : .2) * dt * (this.handbrake ? 2.4 : 1);
260:     }
261:     const nf = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
262:     const nr = new THREE.Vector2(-nf.y, nf.x);
263:     this.velocity.set(nf.x * vf + nr.x * vr, nf.y * vf + nr.y * vr);
264:     this.pos.x += this.velocity.x * dt;
265:     this.pos.z += this.velocity.y * dt;
266:     this.group.rotation.y = this.heading;
267:     // body roll / pitch
268:     if (this.wheels.length) {
269:       this.group.rotation.z = lerp(this.group.rotation.z, -this.steer * clamp(vf / 40, 0, 1) * .055, dt * 5);
270:       this.group.rotation.x = lerp(this.group.rotation.x, clamp((this.throttle - this.brakeInput) * .012, -.02, .02), dt * 4);
271:     }
272:     this.speed = vf;
273:     this.speedKmh = Math.abs(vf) * 3.6;
274:     this.brakeOn = this.brakeInput > 0 || (this.throttle === 0 && Math.abs(vf) > .2) || this.handbrake;
275:     // fuel
276:     if (engine) {
277:       this.fuel = Math.max(0, this.fuel - dt * (0.011 + Math.abs(vf) * .00075 * (this.throttle > 0 ? 2.2 : 1)));
278:     }
279:     // collisions
280:     this.resolveWorldCollisions(dt, vf);
281:     this.animateWheels(dt);
282:     this.animateLights(elapsed, night, controls);
283:     if (this.health < 55) this.game.effects.smokeAtVehicle(this, dt);
284:     if (hasFuel === false && engine) { this.engineOn = false; }
285:   }
286: 
287:   updateHelicopter(dt, controls, night) {
288:     const cfg = this.cfg;
289:     const hasFuel = this.fuel > 0.1;
290:     const engine = this.engineOn && hasFuel;
291:     this.throttle = controls.throttle || 0;
292:     this.brakeInput = controls.brake || 0;
293:     this.steer = controls.steer || 0;
294:     const up = controls.up || 0, down = controls.down || 0;
295:     const targetVY = engine ? (up - down) * 11 : -9;
296:     this.verticalVelocity = lerp(this.verticalVelocity, targetVY, dt * 2.2);
297:     this.altitude = Math.max(0.5, this.altitude + this.verticalVelocity * dt);
298:     const f = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
299:     let forwardSpeed = this.velocity.dot(f);
300:     const targetSpeed = engine ? this.throttle * cfg.maxSpeed - this.brakeInput * 10 : 0;
301:     forwardSpeed = lerp(forwardSpeed, targetSpeed, dt * .7);
302:     this.heading = normAngle(this.heading + this.steer * dt * (1.15 + clamp(Math.abs(forwardSpeed) / 40, 0, .4)));
303:     const nf = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
304:     this.velocity.set(nf.x * forwardSpeed, nf.y * forwardSpeed);
305:     this.pos.x += this.velocity.x * dt;
306:     this.pos.z += this.velocity.y * dt;
307:     this.pos.y = lerp(this.pos.y, this.altitude + Math.sin(performance.now() * .001) * .06, dt * 5);
308:     this.group.rotation.y = this.heading;
309:     this.group.rotation.z = lerp(this.group.rotation.z, -this.steer * .18 - this.velocity.x * .001, dt * 2);
310:     this.group.rotation.x = lerp(this.group.rotation.x, clamp(-forwardSpeed * .004, -.16, .16), dt * 2);
311:     this.speed = Math.abs(forwardSpeed);
312:     this.speedKmh = Math.abs(forwardSpeed) * 3.6;
313:     this.fuel = Math.max(0, this.fuel - dt * (0.03 + (up ? .04 : 0)));
314:     this.rotorAngle += dt * (engine ? 42 : 8);
315:     this.model.rotor.rotation.y = this.rotorAngle;
316:     if (this.model.tailRotor) this.model.tailRotor.rotation.x = this.rotorAngle * 1.4;
317:     if (this.rotor) this.rotor.rotation.y = this.rotorAngle;
318:     this.brakeOn = false;
319:     // building crash
320:     if (this.altitude < 30) {
321:       const hit = this.game.city.collideCircle(this.pos.x, this.pos.z, 3);
322:       if (hit && hit.box.height > this.pos.y) {
323:         this.pos.x -= hit.nx * hit.pen; this.pos.z -= hit.nz * hit.pen;
324:         this.health = Math.max(0, this.health - 12);
325:         this.game.effects.sparksAt(this.pos.x, this.pos.y, this.pos.z, 14);
326:         this.verticalVelocity = 2;
327:       }
328:     }
329:     if (this.pos.y < 2.2) {
330:       this.pos.y = 2.2; this.altitude = 2.2; this.verticalVelocity = 0;
331:       if (controls.up) { this.altitude = 2.4; }
332:     }
333:     if (this.health < 55) this.game.effects.smokeAtVehicle(this, dt);
334:     this.animateLights(performance.now() / 1000, night, controls);
335:     if (!engine && this.altitude > 1) { this.altitude = Math.max(.5, this.altitude - dt * 4); }
336:   }
337: 
338:   updateBoat(dt, controls, weather, night) {
339:     const cfg = this.cfg;
340:     const f = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
341:     const r = new THREE.Vector2(-f.y, f.x);
342:     let vf = this.velocity.dot(f);
343:     let vr = this.velocity.dot(r);
344:     this.throttle = controls.throttle || 0;
345:     this.brakeInput = controls.brake || 0;
346:     this.steer = controls.steer || 0;
347:     const engine = this.engineOn && this.fuel > .1;
348:     if (engine && this.throttle > 0) vf += cfg.accel * this.throttle * dt * (1 - clamp(vf / cfg.maxSpeed, 0, 1) * .6);
349:     if (this.brakeInput > 0) vf -= cfg.brake * this.brakeInput * dt;
350:     vf *= 1 - dt * .25;
351:     vf = clamp(vf, -4, cfg.maxSpeed);
352:     vr *= Math.exp(-1.6 * dt);
353:     this.heading = normAngle(this.heading + this.steer * 1.1 * clamp(Math.abs(vf) / 8, 0, 1) * dt);
354:     const nf = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
355:     this.velocity.set(nf.x * vf, nf.y * vf);
356:     this.pos.x += this.velocity.x * dt;
357:     this.pos.z += this.velocity.y * dt;
358:     // water bounds
359:     if (this.pos.z < 492) { this.pos.z = 492; this.velocity.y = Math.abs(this.velocity.y) * .2; vf *= .2; }
360:     if (this.pos.z > 1400) this.pos.z = 1400;
361:     this.pos.y = .25 + Math.sin(performance.now() * .0012 + this.pos.x * .01) * .12;
362:     this.group.rotation.y = this.heading;
363:     this.group.rotation.z = lerp(this.group.rotation.z, this.steer * .08, dt * 3);
364:     this.group.rotation.x = lerp(this.group.rotation.x, Math.sin(performance.now() * .0015) * .02, dt * 2);
365:     this.speed = vf;
366:     this.speedKmh = Math.abs(vf) * 3.6;
367:     this.fuel = Math.max(0, this.fuel - dt * (.02 + this.throttle * .04));
368:     this.animateLights(performance.now() / 1000, night, controls);
369:     if (Math.abs(vf) > 3) {
370:       this.wakeAcc += dt;
371:       if (this.wakeAcc > .08) {
372:         this.wakeAcc = 0;
373:         const back = new THREE.Vector2(-Math.sin(this.heading), -Math.cos(this.heading));
374:         this.game.effects.wakes.spawn(this.pos.x + back.x * 3.2, this.pos.y + .2, this.pos.z + back.y * 3.2, {
375:           color: 0xd7f1ff, size: 1.2, grow: 2.4, life: .9, vy: .2, vx: rand(-.4, .4), vz: rand(-.4, .4), drag: .9,
376:         });
377:       }
378:     }
379:     if (this.health < 55) this.game.effects.smokeAtVehicle(this, dt);
380:   }
381: 
382:   resolveWorldCollisions(dt, vf) {
383:     const len = this.cfg.len;
384:     const rad = this.cfg.wid * .46;
385:     const offsets = [-len * .32, 0, len * .32];
386:     const f = { x: Math.sin(this.heading), z: Math.cos(this.heading) };
387:     let hitAny = false, maxPen = 0, hitN = null;
388:     for (const o of offsets) {
389:       const cx = this.pos.x + f.x * o, cz = this.pos.z + f.z * o;
390:       const hit = this.game.city.collideCircle(cx, cz, rad);
391:       if (hit) {
392:         this.pos.x += hit.nx * hit.pen;
393:         this.pos.z += hit.nz * hit.pen;
394:         hitAny = true;
395:         if (hit.pen > maxPen) { maxPen = hit.pen; hitN = hit; }
396:       }
397:     }
398:     if (hitAny) {
399:       const impact = Math.abs(vf) + maxPen * 8;
400:       if (impact > 1.6) {
401:         const nx = hitN.nx, nz = hitN.nz;
402:         const vn = this.velocity.x * nx + this.velocity.y * nz;
403:         if (vn < 0) {
404:           this.velocity.x -= nx * vn * 1.35;
405:           this.velocity.y -= nz * vn * 1.35;
406:         }
407:         this.velocity.multiplyScalar(.72);
408:         const dmg = clamp((impact - 1.2) * .9, 0, 30);
409:         this.applyDamage(dmg, { x: this.pos.x + f.x * (len * .32), y: this.pos.y + .7, z: this.pos.z + f.z * (len * .32) });
410:         this.game.audio?.crash(impact);
411:         if (impact > 4) this.game.camShake = Math.max(this.game.camShake, Math.min(1, impact / 20));
412:       }
413:     }
414:   }
415: 
416:   animateWheels(dt) {
417:     const roll = this.speed * dt / (this.cfg.wheelR || .35);
418:     for (const w of this.wheels) {
419:       w.mesh.rotation.x += roll;
420:       if (w.front) w.mesh.rotation.y = this.steer * .42;
421:     }
422:   }
423: 
424:   animateLights(elapsed, night, controls) {
425:     const lightsOn = this.lightsOn || night > .5;
426:     if (lightsOn) this.lightsOn = true;
427:     const left = this.indicator === -1 || controls?.left;
428:     const right = this.indicator === 1 || controls?.right;
