179:   drawMinimap(dt) {
180:     const canvas = this.el.minimap;
181:     if (!canvas) return;
182:     const ctx = canvas.getContext('2d');
183:     const g = this.game, p = g.player;
184:     const W = canvas.width, H = canvas.height;
185:     const scale = 2.15;
186:     ctx.clearRect(0, 0, W, H);
187:     ctx.save();
188:     ctx.translate(W / 2, H / 2);
189:     // background
190:     ctx.fillStyle = '#111922'; ctx.fillRect(-W / 2, -H / 2, W, H);
191:     const toS = (x, z) => [(x - p.pos.x) * scale, (z - p.pos.z) * scale];
192:     // water
193:     const [wx, wy] = toS(0, 490);
194:     if (wy < H / 2) {
195:       ctx.fillStyle = '#0e3547';
196:       ctx.fillRect(-W / 2, wy, W, H / 2 - wy);
197:     }
198:     // blocks
199:     for (const b of g.city.blocks) {
200:       const [sx, sy] = toS(b.x, b.z);
201:       if (Math.abs(sx) > W / 2 + 60 || Math.abs(sy) > H / 2 + 60) continue;
202:       const size = 68 * scale;
203:       ctx.fillStyle = DISTRICT_COLORS[b.district] || '#2c3238';
204:       ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
205:       if (b.isPark) { ctx.fillStyle = '#2f5034'; ctx.fillRect(sx - size / 2, sy - size / 2, size, size); }
206:     }
207:     // roads
208:     ctx.strokeStyle = 'rgba(140,160,175,.32)';
209:     ctx.lineWidth = 8 * scale * .45;
210:     for (let i = 0; i < 9; i++) {
211:       const p0 = toS(NODE_POS(i), -CITY_EXTENT); const p1 = toS(NODE_POS(i), CITY_EXTENT);
212:       ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke();
213:       const q0 = toS(-CITY_EXTENT, NODE_POS(i)); const q1 = toS(CITY_EXTENT, NODE_POS(i));
214:       ctx.beginPath(); ctx.moveTo(q0[0], q0[1]); ctx.lineTo(q1[0], q1[1]); ctx.stroke();
215:     }
216:     // poi markers
217:     const near = g.city.pois.filter(poi => Math.hypot(poi.x - p.pos.x, poi.z - p.pos.z) < 140);
218:     for (const poi of near) {
219:       const [sx, sy] = toS(poi.x, poi.z);
220:       ctx.fillStyle = this.poiColor(poi.type);
221:       ctx.beginPath(); ctx.arc(sx, sy, 4.2, 0, Math.PI * 2); ctx.fill();
222:     }
223:     // events
224:     for (const m of g.events?.mapMarkers() || []) {
225:       const [sx, sy] = toS(m.x, m.z);
226:       if (Math.abs(sx) > W / 2 || Math.abs(sy) > H / 2) continue;
227:       ctx.fillStyle = m.type === 'fire' ? '#ff5b2a' : '#ffb457';
228:       ctx.beginPath(); ctx.arc(sx, sy, 5, 0, Math.PI * 2); ctx.fill();
229:     }
230:     // job
231:     if (g.jobs.current) {
232:       const t = g.jobs.current.stage === 'pickup' ? g.jobs.current.pickup : g.jobs.current.dropoff;
233:       const [sx, sy] = toS(t.x, t.z);
234:       ctx.fillStyle = '#ffb457'; ctx.beginPath(); ctx.arc(sx, sy, 5.5, 0, Math.PI * 2); ctx.fill();
235:       ctx.strokeStyle = 'rgba(255,180,87,.5)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(sx, sy, 10, 0, Math.PI * 2); ctx.stroke();
236:     }
237:     if (this.gps) {
238:       const [sx, sy] = toS(this.gps.x, this.gps.z);
239:       ctx.strokeStyle = '#5be0ff'; ctx.lineWidth = 2;
240:       ctx.setLineDash([4, 4]); ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(sx, sy); ctx.stroke(); ctx.setLineDash([]);
241:       ctx.fillStyle = '#5be0ff'; ctx.beginPath(); ctx.arc(sx, sy, 4, 0, Math.PI * 2); ctx.fill();
242:     }
243:     // vehicles
244:     if (g.vehicles) for (const v of g.vehicles.vehicles) {
245:       const [sx, sy] = toS(v.pos.x, v.pos.z);
246:       if (Math.abs(sx) > W / 2 || Math.abs(sy) > H / 2) continue;
247:       if (v === g.vehicles.playerVehicle) continue;
248:       ctx.fillStyle = v.service ? (v.service === 'police' ? '#5b8fff' : v.service === 'fire' ? '#ff5b5b' : '#ffffff') : 'rgba(200,220,240,.42)';
249:       ctx.fillRect(sx - 2, sy - 2, 4, 4);
250:     }
251:     // player arrow
252:     ctx.save();
253:     ctx.rotate(-g.player.heading + Math.PI);
254:     ctx.fillStyle = '#5be0ff';
255:     ctx.shadowColor = '#5be0ff'; ctx.shadowBlur = 10;
256:     ctx.beginPath(); ctx.moveTo(0, 8); ctx.lineTo(-5, -6); ctx.lineTo(0, -3); ctx.lineTo(5, -6); ctx.closePath(); ctx.fill();
257:     ctx.restore();
258:     ctx.restore();
259:     // ring vignette
260:     const grad = ctx.createRadialGradient(W / 2, H / 2, W * .34, W / 2, H / 2, W * .5);
261:     grad.addColorStop(0, 'rgba(0,0,0,0)'); grad.addColorStop(1, 'rgba(5,9,15,.72)');
262:     ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
263:   }
