269:   buildMapCache() {
270:     if (this.mapCache) return;
271:     const c = document.createElement('canvas'); c.width = 1400; c.height = 1000;
272:     const ctx = c.getContext('2d');
273:     const g = this.game;
274:     ctx.fillStyle = '#0b121b'; ctx.fillRect(0, 0, 1400, 1000);
275:     const toP = (x, z) => [x + 700, z + 500];
276:     // water
277:     ctx.fillStyle = '#0d2c3d'; ctx.fillRect(0, 986, 1400, 200);
278:     ctx.fillStyle = '#3b4330'; ctx.fillRect(0, 0, 1400, 1000);
279:     // blocks
280:     const blockSize = 80;
281:     for (const b of g.city.blocks) {
282:       const [x, y] = toP(b.x, b.z);
283:       ctx.fillStyle = b.isPark ? '#24472c' : (DISTRICT_COLORS[b.district] || '#2f353b');
284:       ctx.fillRect(x - blockSize / 2, y - blockSize / 2, blockSize, blockSize);
285:       if (b.district === 'downtown') {
286:         ctx.fillStyle = 'rgba(180,210,235,.09)';
287:         ctx.fillRect(x - 20, y - 20, 40, 40);
288:       }
289:     }
290:     // roads
291:     ctx.strokeStyle = '#4a5259'; ctx.lineWidth = 15; ctx.lineCap = 'butt';
292:     for (let i = 0; i < 9; i++) {
293:       let [x, y] = toP(NODE_POS(i), -CITY_EXTENT); ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 2 * CITY_EXTENT); ctx.stroke();
294:       let [x2, y2] = toP(-CITY_EXTENT, NODE_POS(i)); ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2 + 2 * CITY_EXTENT, y2); ctx.stroke();
295:     }
296:     ctx.strokeStyle = 'rgba(230,230,210,.18)'; ctx.lineWidth = 1; ctx.setLineDash([6, 8]);
297:     for (let i = 0; i < 9; i++) {
298:       let [x, y] = toP(NODE_POS(i), -CITY_EXTENT); ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 2 * CITY_EXTENT); ctx.stroke();
299:       let [x2, y2] = toP(-CITY_EXTENT, NODE_POS(i)); ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2 + 2 * CITY_EXTENT, y2); ctx.stroke();
300:     }
301:     ctx.setLineDash([]);
302:     // elevated monorail
303:     ctx.strokeStyle = 'rgba(177,140,255,.4)'; ctx.lineWidth = 3;
304:     ctx.strokeRect(700 - 250, 500 - 250, 500, 500);
305:     // rail
306:     ctx.strokeStyle = 'rgba(220,180,90,.5)'; ctx.lineWidth = 4;
307:     ctx.beginPath(); ctx.moveTo(0, 54); ctx.lineTo(1400, 54); ctx.stroke();
308:     // airport
309:     ctx.strokeStyle = '#5d5d5d'; ctx.lineWidth = 26;
310:     ctx.beginPath(); ctx.moveTo(1370, 340); ctx.lineTo(1370, 660); ctx.stroke();
311:     ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = 2; ctx.setLineDash([10, 12]);
312:     ctx.beginPath(); ctx.moveTo(1370, 340); ctx.lineTo(1370, 660); ctx.stroke(); ctx.setLineDash([]);
313:     // block labels
314:     ctx.fillStyle = 'rgba(190,215,240,.28)'; ctx.font = '600 11px Inter, sans-serif'; ctx.textAlign = 'center';
315:     ctx.fillText('DOWNTOWN', 700, 490);
316:     ctx.fillText('INDUSTRIAL', 500, 185);
317:     ctx.fillText('PINE HILLS', 1080, 430);
318:     ctx.fillText('WEST END', 250, 560);
319:     ctx.fillText('HARBORFRONT', 700, 905);
320:     // POIs
321:     for (const p of g.city.pois) {
322:       const [x, y] = toP(p.x, p.z);
323:       ctx.fillStyle = this.poiColor(p.type);
324:       ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI * 2); ctx.fill();
325:       ctx.fillStyle = 'rgba(220,238,255,.7)'; ctx.font = '500 9px Inter, sans-serif';
326:       ctx.fillText(p.name.toUpperCase(), x, y - 10);
327:     }
328:     this.mapCache = c;
329:   }
