348:       ctx.beginPath(); ctx.arc(x, y, 8, 0, Math.PI * 2); ctx.fill();
349:       ctx.strokeStyle = 'rgba(255,180,87,.4)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(x, y, 15 + Math.sin(performance.now() * .003) * 3, 0, Math.PI * 2); ctx.stroke();
