import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://127.0.0.1:5173', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.novaCity?.ready, null, { timeout: 120000 });
await page.locator('#btn-start').click();
await page.locator('[data-start-mode="phone"]').click();
await page.waitForFunction(() => window.novaCity?.mode === 'playing');
await page.waitForTimeout(1000);
const start = await page.evaluate(() => ({
  mode: window.novaCity.settings.mode,
  body: document.body.className,
  controlsDisplay: getComputedStyle(document.querySelector('#phone-controls')).display,
  save: localStorage.getItem('novacity-settings-v1')
}));
if (start.mode !== 'phone' || !start.body.includes('game-playing') || start.controlsDisplay === 'none') throw new Error('Phone mode did not enable controls: ' + JSON.stringify(start));
const stick = await page.locator('#touch-stick').boundingBox();
await page.mouse.move(stick.x + stick.width / 2, stick.y + stick.height / 2);
await page.mouse.down();
await page.mouse.move(stick.x + stick.width * .78, stick.y + stick.height * .45, { steps: 3 });
const touch = await page.evaluate(() => ({ x: window.novaCity.touch.x, y: window.novaCity.touch.y }));
await page.mouse.up();
if (touch.x < 0.2) throw new Error('Touch joystick did not change game input: ' + JSON.stringify(touch));
await page.locator('[data-touch-action="phone"]').click();
const overlay = await page.evaluate(() => ({ open: !document.querySelector('#overlay-root').classList.contains('hidden'), controlsDisplay: getComputedStyle(document.querySelector('#phone-controls')).display, paused: window.novaCity.paused }));
if (!overlay.open || overlay.controlsDisplay !== 'none') throw new Error('Phone overlay did not hide controls: ' + JSON.stringify(overlay));
await page.keyboard.press('Escape');
await page.waitForFunction(() => !document.body.classList.contains('ui-overlay-open'));
const resumed = await page.evaluate(() => ({ controlsDisplay: getComputedStyle(document.querySelector('#phone-controls')).display, paused: window.novaCity.paused }));
if (resumed.controlsDisplay === 'none' || resumed.paused) throw new Error('Closing overlay did not restore play controls: ' + JSON.stringify(resumed));
await page.screenshot({ path: 'screenshots/phone-mode-gameplay.png' });
const station = await page.evaluate(() => {
  const g = window.novaCity;
  const s = g.city.monorail.stations[0];
  g.player.setPosition(s.tower.x + 8, s.tower.z + 11, .2);
  g.player.cameraYaw = s.ang + Math.PI;
  g.player.cameraPitch = .18;
  g.player.cameraDist = 22;
  g.city.monorail.riding = false;
  return { name: s.name, x: s.tower.x, z: s.tower.z, trainPosition: g.city.monorail.group.position.toArray() };
});
await page.waitForTimeout(2500);
await page.screenshot({ path: 'screenshots/train-scene-in-game.png' });
const trainInfo = await page.evaluate(() => ({
  stationCount: window.novaCity.city.monorail.stations.length,
  mode: window.novaCity.mode,
  trainPosition: window.novaCity.city.monorail.group.position.toArray(),
  trainVisible: window.novaCity.city.monorail.group.visible,
  canvas: [document.querySelector('#game').width, document.querySelector('#game').height]
}));
console.log(JSON.stringify({ start, touch, overlay, resumed, station, trainInfo, errors }, null, 2));
await browser.close();

