import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://127.0.0.1:5173', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.novaCity?.ready, null, { timeout: 120000 });
await page.locator('#btn-start').click();
await page.locator('[data-start-mode="pc"]').click();
await page.waitForFunction(() => window.novaCity?.mode === 'playing');
await page.waitForTimeout(300);
const before = await page.evaluate(() => ({ pos: window.novaCity.player.pos.toArray(), yaw: window.novaCity.player.cameraYaw, mode: window.novaCity.settings.mode }));
await page.keyboard.down('KeyW');
await page.waitForTimeout(700);
await page.keyboard.up('KeyW');
const afterKey = await page.evaluate(() => ({ pos: window.novaCity.player.pos.toArray(), input: { ...window.novaCity.input } }));
await page.mouse.move(500, 300);
await page.mouse.down();
await page.mouse.move(560, 320, { steps: 3 });
await page.mouse.up();
const afterMouse = await page.evaluate(() => ({ yaw: window.novaCity.player.cameraYaw, pitch: window.novaCity.player.cameraPitch, pointerLocked: document.pointerLockElement === window.novaCity.canvas }));
await page.evaluate(() => {
  const pads = [];
  const buttons = Array.from({ length: 10 }, (_, i) => ({ pressed: false, value: 0 }));
  pads[0] = { connected: true, index: 0, id: 'Synthetic test controller', axes: [-0.8, -0.9, 0.4, -0.3], buttons };
  Object.defineProperty(navigator, 'getGamepads', { configurable: true, value: () => pads });
});
await page.waitForTimeout(150);
const gamepad = await page.evaluate(() => ({ id: window.novaCity.gamepadId, input: { ...window.novaCity.input }, vehicle: { ...window.novaCity.controls.vehicle }, yaw: window.novaCity.player.cameraYaw, pitch: window.novaCity.player.cameraPitch }));
if (afterKey.pos[2] >= before.pos[2]) throw new Error('W key failed to move forward: ' + JSON.stringify({ before, afterKey }));
if (Math.abs(afterMouse.yaw - before.yaw) < .05) throw new Error('Mouse drag failed to rotate camera: ' + JSON.stringify({ before, afterMouse }));
if (gamepad.id !== 0 || !gamepad.input.forward || !gamepad.input.left) throw new Error('Gamepad axes failed: ' + JSON.stringify(gamepad));
if (errors.length) throw new Error('Page errors: ' + errors.join('; '));
console.log(JSON.stringify({ before, afterKey, afterMouse, gamepad, errors }, null, 2));
await browser.close();

