import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://127.0.0.1:5173', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.novaCity?.ready, null, { timeout: 120000 });
await page.locator('#btn-start').click();
await page.locator('[data-start-mode="phone"]').click();
await page.waitForFunction(() => window.novaCity?.mode === 'playing');
await page.waitForTimeout(500);
await page.evaluate(() => {
  const g = window.novaCity;
  const v = g.vehicles.startCar;
  v.pos.set(g.player.pos.x, .02, g.player.pos.z);
  v.heading = g.player.heading;
  v.group.position.set(v.pos.x, v.pos.y, v.pos.z);
  g.enterVehicle(v);
});
await page.waitForFunction(() => document.body.classList.contains('phone-driving'));
const display = await page.locator('[data-touch-action="throttle"]').evaluate(el => ({ display: getComputedStyle(el).display, rect: el.getBoundingClientRect().toJSON() }));
if (display.display === 'none') throw new Error('Throttle control is hidden while driving: ' + JSON.stringify(display));
const before = await page.evaluate(() => { const v = window.novaCity.vehicles.playerVehicle; return { x: v.pos.x, z: v.pos.z, speed: v.speed }; });
const gas = await page.locator('[data-touch-action="throttle"]').boundingBox();
await page.mouse.move(gas.x + gas.width / 2, gas.y + gas.height / 2);
await page.mouse.down();
await page.waitForTimeout(1200);
const accelerating = await page.evaluate(() => { const g = window.novaCity, v = g.vehicles.playerVehicle; return { throttle: g.touch.throttle, speed: v.speed, x: v.pos.x, z: v.pos.z, input: { ...g.controls.vehicle } }; });
await page.mouse.up();
await page.waitForTimeout(180);
if (!accelerating.touch || accelerating.speed < 1 || Math.hypot(accelerating.x - before.x, accelerating.z - before.z) < .5) throw new Error('Touch throttle did not accelerate/move: ' + JSON.stringify({ before, accelerating }));
const brake = await page.locator('[data-touch-action="brake"]').boundingBox();
await page.mouse.move(brake.x + brake.width / 2, brake.y + brake.height / 2);
await page.mouse.down();
await page.waitForTimeout(750);
const braking = await page.evaluate(() => { const g = window.novaCity, v = g.vehicles.playerVehicle; return { brake: g.touch.brake, speed: v.speed, control: g.controls.vehicle.brake }; });
await page.mouse.up();
if (!braking.brake || braking.control < .99) throw new Error('Touch brake did not register: ' + JSON.stringify(braking));
const stick = await page.locator('#touch-stick').boundingBox();
await page.mouse.move(stick.x + stick.width / 2, stick.y + stick.height / 2);
await page.mouse.down();
await page.mouse.move(stick.x + stick.width * .78, stick.y + stick.height * .45, { steps: 4 });
await page.waitForTimeout(150);
const steering = await page.evaluate(() => ({ x: window.novaCity.touch.x, steer: window.novaCity.controls.vehicle.steer, visible: getComputedStyle(document.querySelector('#touch-stick')).display }));
await page.mouse.up();
if (steering.steer < .2 || steering.x < .2) throw new Error('Touch joystick did not steer: ' + JSON.stringify(steering));
await page.locator('[data-touch-action="exit"]').click();
await page.waitForFunction(() => !document.body.classList.contains('phone-driving'));
const exit = await page.evaluate(() => ({ driving: !!window.novaCity.vehicles.playerVehicle, mode: window.novaCity.mode }));
if (exit.driving) throw new Error('Exit button did not exit vehicle');
console.log(JSON.stringify({ display, before, accelerating, braking, steering, exit, errors }, null, 2));
await browser.close();

