112:   lanePoint(tr, ahead = 0) {
113:     const nx = tr.node.x + tr.dir[0] * (tr.t + ahead);
114:     const nz = tr.node.z + tr.dir[1] * (tr.t + ahead);
115:     const rx = -tr.dir[1], rz = tr.dir[0];
116:     return { x: nx + rx * tr.lane, z: nz + rz * tr.lane };
