611: function addCurvedBeam(root, cx, cz, radius, startAngle, endAngle, y, height, width, material) {
612:   const steps = 12;
613:   for (let i = 0; i < steps; i++) {
614:     const a0 = startAngle + (endAngle - startAngle) * i / steps;
615:     const a1 = startAngle + (endAngle - startAngle) * (i + 1) / steps;
616:     const am = (a0 + a1) * .5;
617:     const dx = Math.cos(am) * radius;
618:     const dz = Math.sin(am) * radius;
619:     const span = radius * Math.abs(a1 - a0);
620:     const segment = new THREE.Mesh(new THREE.BoxGeometry(width, height, span + .12), material);
621:     segment.position.set(cx + dx, y, cz + dz);
622:     segment.rotation.y = -am;
623:     segment.castShadow = true;
624:     root.add(segment);
625:   }
626: }
