628: function loopPoints(progress, perimeter, R) {
629:   const seg = perimeter / 4;
630:   let p = progress % perimeter;
631:   if (p < seg) return { x: -R + p, z: -R, angle: 0 };
632:   p -= seg;
633:   if (p < seg) return { x: R, z: -R + p, angle: Math.PI / 2 };
634:   p -= seg;
635:   if (p < seg) return { x: R - p, z: R, angle: Math.PI };
636:   p -= seg;
637:   return { x: -R, z: R - p, angle: -Math.PI / 2 };
638: }
