92:     const rootInv = new THREE.Matrix4().copy(root.matrixWorld).invert();
93: 
94:     const dynamic = new Set();
95:     const markDynamic = (obj) => { if (obj) obj.traverse((o) => dynamic.add(o)); };
96:     markDynamic(this.water);
97:     markDynamic(this.lampGlow);
98:     markDynamic(this.smokeParticles);
99:     markDynamic(this.fireflyPoints);
100:     if (this.monorail) markDynamic(this.monorail.group);
101:     if (this.rail) markDynamic(this.rail.group);
102:     if (this.flyingPlane) markDynamic(this.flyingPlane.group);
103:     for (const c of this.highwayCars) markDynamic(c);
104:     for (const a of this.animated) if (a.mesh) markDynamic(a.mesh);
105: 
106:     const buckets = new Map();
107:     const isDynamic = (o) => {
108:       let p = o;
109:       while (p) { if (dynamic.has(p) || p.userData?.noMerge) return true; p = p.parent; }
110:       return false;
111:     };
112: 
113:     root.traverse((o) => {
114:       if (!o.isMesh || o.isInstancedMesh || o.isSkinnedMesh || o.isPoints || o.isSprite) return;
115:       if (isDynamic(o) || Array.isArray(o.material)) return;
116:       const m = o.material;
117:       if (!m || m.isShaderMaterial || m.transparent || m.opacity < 1 || m.depthWrite === false) return;
118:       if (!(m.isMeshStandardMaterial || m.isMeshBasicMaterial || m.isMeshLambertMaterial || m.isMeshPhongMaterial)) return;
119:       const g = o.geometry;
120:       if (!g || !g.attributes.position || !g.attributes.normal || !g.attributes.uv) return;
121:       if (g.morphAttributes && Object.keys(g.morphAttributes).length) return;
122:       const key = m.uuid;
123:       let b = buckets.get(key);
124:       if (!b) { b = { material: m, geos: [], meshes: [], cast: false, receive: false }; buckets.set(key, b); }
125:       const geo = g.index ? g.toNonIndexed() : g.clone();
126:       for (const name of Object.keys(geo.attributes)) {
127:         if (name !== 'position' && name !== 'normal' && name !== 'uv') geo.deleteAttribute(name);
128:       }
129:       geo.clearGroups();
130:       geo.applyMatrix4(new THREE.Matrix4().multiplyMatrices(rootInv, o.matrixWorld));
131:       b.geos.push(geo); b.meshes.push(o);
132:       b.cast = b.cast || o.castShadow;
133:       b.receive = b.receive || o.receiveShadow;
134:     });
135: 
136:     for (const b of buckets.values()) {
137:       if (b.meshes.length < 2) {
138:         for (const g of b.geos) g.dispose();
139:         continue;
140:       }
141:       const merged = mergeGeometries(b.geos, false);
142:       for (const g of b.geos) g.dispose();
143:       if (!merged) continue;
144:       const mesh = new THREE.Mesh(merged, b.material);
145:       mesh.name = `merged-${b.material.uuid}`;
146:       mesh.castShadow = b.cast;
147:       mesh.receiveShadow = b.receive;
148:       root.add(mesh);
149:       for (const o of b.meshes) o.parent?.remove(o);
150:     }
151:     this.mergedStaticMeshes = root.children.filter((o) => o.name.startsWith('merged-')).length;
152:   }
