228:     const geo = this.roadPlaneGeometry();
229:     this.roadMeshes = [];
230:     for (let i = 0; i < GRID; i++) {
231:       const p = NODE_POS(i);
232:       const v = new THREE.Mesh(geo, mat);
233:       v.position.set(p, 0.02, 0);
234:       v.receiveShadow = true;
235:       this.root.add(v); this.roadMeshes.push(v);
236:       const h = new THREE.Mesh(geo, mat);
237:       h.rotation.y = Math.PI / 2;
238:       h.position.set(0, 0.021, p);
239:       h.receiveShadow = true;
240:       this.root.add(h); this.roadMeshes.push(h);
241:     }
242:     // intersections
243:     const ig = new THREE.PlaneGeometry(ROAD_W, ROAD_W); ig.rotateX(-Math.PI / 2);
244:     const im = new THREE.MeshStandardMaterial({ color: 0x23262b, roughness: 0.93 });
245:     for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
246:       const m = new THREE.Mesh(ig, im);
247:       m.position.set(NODE_POS(i), 0.035, NODE_POS(j));
248:       this.root.add(m);
