251:     // lane dashes
252:     const dashGeo = new THREE.BoxGeometry(0.16, 0.012, 3.2);
253:     const dashMat = new THREE.MeshStandardMaterial({ color: 0xd9d6c4, roughness: 0.8 });
254:     const dashes = [];
255:     for (let i = 0; i < GRID; i++) {
256:       for (let s = -CITY_EXTENT - 10; s < CITY_EXTENT + 10; s += 8) {
257:         if (Math.abs(((s + 4 + 48) % 96 + 96) % 96 - 48) < 10) continue;
258:         dashes.push([NODE_POS(i), s, 0]);
259:         dashes.push([s, NODE_POS(i), Math.PI / 2]);
260:       }
261:     }
262:     const dMesh = new THREE.InstancedMesh(dashGeo, dashMat, dashes.length);
263:     const tmp = new THREE.Object3D();
264:     dashes.forEach(([x, z, r], k) => {
265:       tmp.position.set(x, 0.055, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
266:       dMesh.setMatrixAt(k, tmp.matrix);
267:     });
268:     dMesh.instanceMatrix.needsUpdate = true;
269:     this.root.add(dMesh);
270: 
271:     // crosswalks
272:     const cwGeo = new THREE.BoxGeometry(0.72, 0.014, 3.5);
273:     const cwMat = new THREE.MeshStandardMaterial({ color: 0xe9e7df, roughness: 0.75 });
274:     const cws = [];
275:     for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
276:       const x = NODE_POS(i), z = NODE_POS(j);
277:       for (let a = -3; a <= 3; a++) {
278:         cws.push([x + a * 1.1, z - HALF_ROAD - 2.1, 0]);
279:         cws.push([x + a * 1.1, z + HALF_ROAD + 2.1, 0]);
280:         cws.push([x - HALF_ROAD - 2.1, z + a * 1.1, Math.PI / 2]);
281:         cws.push([x + HALF_ROAD + 2.1, z + a * 1.1, Math.PI / 2]);
282:       }
283:     }
284:     const cwMesh = new THREE.InstancedMesh(cwGeo, cwMat, cws.length);
285:     cws.forEach(([x, z, r], k) => {
286:       tmp.position.set(x, 0.06, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
287:       cwMesh.setMatrixAt(k, tmp.matrix);
288:     });
289:     this.root.add(cwMesh);
290: 
291:     // edge lines
292:     const edgeGeo = new THREE.PlaneGeometry(0.14, 840); edgeGeo.rotateX(-Math.PI / 2);
293:     const edgeMat = new THREE.MeshStandardMaterial({ color: 0xc9c6b7, roughness: 0.85 });
294:     for (let i = 0; i < GRID; i++) {
295:       for (const side of [-1, 1]) {
296:         const v = new THREE.Mesh(edgeGeo, edgeMat);
297:         v.position.set(NODE_POS(i) + side * (HALF_ROAD - 0.45), 0.05, 0);
298:         this.root.add(v);
299:         const h = new THREE.Mesh(edgeGeo, edgeMat);
300:         h.rotation.y = Math.PI / 2;
301:         h.position.set(0, 0.05, NODE_POS(i) + side * (HALF_ROAD - 0.45));
302:         this.root.add(h);
