307:   buildBlocks(rng) {
308:     const sidewalkGeo = new THREE.PlaneGeometry(SPACING - ROAD_W, SPACING - ROAD_W);
309:     sidewalkGeo.rotateX(-Math.PI / 2);
310:     const swMat = this.mats.sidewalk.clone();
311:     swMat.map = this.mats.sidewalk.map.clone();
312:     swMat.map.repeat.set(12, 12);
313:     swMat.map.needsUpdate = true;
314:     this.sidewalkMat = swMat;
315:     this.sidewalkMesh = new THREE.InstancedMesh(sidewalkGeo, swMat, 64);
316:     const tmp = new THREE.Object3D();
317:     let swIndex = 0;
318: 
319:     const lotMatConcrete = this.mats.lot.clone();
320:     lotMatConcrete.map = this.mats.lot.map.clone(); lotMatConcrete.map.repeat.set(9, 9);
321:     const lotMatGrass = this.mats.grass.clone();
322:     lotMatGrass.map = this.mats.grass.map.clone(); lotMatGrass.map.repeat.set(9, 9);
323:     const lots = { concrete: [], grass: [] };
324: 
325:     const curbGeo = new THREE.BoxGeometry(68, 0.16, 0.28);
326:     const curbs = [];
327: 
328:     for (let bi = 0; bi < 8; bi++) {
329:       for (let bj = 0; bj < 8; bj++) {
330:         const x = BLOCK_CENTER(bi), z = BLOCK_CENTER(bj);
331:         const special = SPECIAL[`${bi},${bj}`] || null;
332:         const district = this.districtForBlock(bi, bj, special);
333:         const block = { bi, bj, x, z, district, special };
334:         this.blocks.push(block);
335: 
336:         tmp.position.set(x, 0.1, z); tmp.rotation.set(0, 0, 0); tmp.scale.set(1, 1, 1); tmp.updateMatrix();
337:         this.sidewalkMesh.setMatrixAt(swIndex++, tmp.matrix);
338: 
339:         const isGreen = ['suburb', 'park', 'residential'].includes(district) || special === 'park';
340:         (isGreen ? lots.grass : lots.concrete).push([x, z]);
341:         curbs.push([x, z - 34, 0], [x, z + 34, 0], [x - 34, z, Math.PI / 2], [x + 34, z, Math.PI / 2]);
342: 
343:         this.buildBlockContent(block, rng);
344:       }
345:     }
346:     this.root.add(this.sidewalkMesh);
347:     this.lotMeshes = [];
348:     for (const [key, arr] of Object.entries(lots)) {
349:       if (!arr.length) continue;
350:       const geo = new THREE.PlaneGeometry(68, 68); geo.rotateX(-Math.PI / 2);
351:       const mesh = new THREE.InstancedMesh(geo, key === 'grass' ? lotMatGrass : lotMatConcrete, arr.length);
352:       arr.forEach(([x, z], i) => { tmp.position.set(x, 0.15, z); tmp.updateMatrix(); mesh.setMatrixAt(i, tmp.matrix); });
353:       mesh.receiveShadow = true;
354:       this.root.add(mesh); this.lotMeshes.push(mesh);
355:     }
356:     const curbMat = new THREE.MeshStandardMaterial({ color: 0x8f8f8a, roughness: 0.95 });
357:     const curbMesh = new THREE.InstancedMesh(curbGeo, curbMat, curbs.length);
358:     curbs.forEach(([x, z, r], i) => {
359:       tmp.position.set(x, 0.18, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
360:       curbMesh.setMatrixAt(i, tmp.matrix);
361:     });
362:     this.root.add(curbMesh);
363:   }
