365:   districtForBlock(bi, bj, special) {
366:     if (special === 'park') return 'park';
367:     if (special === 'suburb') return 'suburb';
368:     if (special === 'industrial') return 'industrial';
369:     if (special === 'airport') return 'airport';
370:     if (bj <= 1) return 'industrial';
371:     if (bi >= 6 && bj >= 2 && bj <= 5) return 'suburb';
372:     if (bj >= 6) return 'waterfront';
373:     if (bi <= 2 && bj >= 3) return 'residential';
374:     if (bi >= 3 && bi <= 5 && bj >= 2 && bj <= 5) return 'downtown';
375:     return 'midtown';
376:   }
