378:   buildBlockContent(block, rng) {
379:     const { bi, bj, x, z, district, special } = block;
380:     if (special === 'park') { this.buildPark(block, rng); return; }
381:     if (special === 'hospital') { this.buildHospital(block); return; }
382:     if (special === 'police') { this.buildPolice(block); return; }
383:     if (special === 'fire') { this.buildFireStation(block); return; }
384:     if (special === 'garage') { this.buildGarage(block); return; }
385:     if (special === 'dealership') { this.buildDealership(block); return; }
386:     if (special === 'apartment') { this.buildApartment(block); return; }
387:     if (special === 'shop') { this.buildShop(block); return; }
388:     if (special === 'office') { this.buildOffice(block); return; }
389:     if (special === 'hotel') { this.buildHotel(block); return; }
390:     if (special === 'industrial') { this.buildFactory(block, rng); return; }
391:     if (district === 'downtown') this.buildDowntown(block, rng);
392:     else if (district === 'industrial') this.buildIndustrial(block, rng);
393:     else if (district === 'suburb') this.buildSuburb(block, rng);
394:     else if (district === 'waterfront') this.buildWaterfront(block, rng);
395:     else this.buildMidrise(block, rng);
396:   }
