402:   facadeGeometry(w, h, d) {
403:     const geo = new THREE.BoxGeometry(w, h, d);
404:     const uv = geo.attributes.uv;
405:     const reps = [
406:       [d, h], [d, h], [w, d], [w, d], [w, h], [w, h],
407:     ];
408:     for (let f = 0; f < 6; f++) {
409:       const rx = reps[f][0] / 12, ry = reps[f][1] / 13;
410:       for (let k = 0; k < 4; k++) {
411:         const idx = f * 4 + k;
412:         uv.setXY(idx, uv.getX(idx) * rx, uv.getY(idx) * ry);
413:       }
414:     }
415:     uv.needsUpdate = true;
416:     return geo;
417:   }
