448:       spire.position.y = 4 + rng() * 4; g.add(spire);
449:       const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.26, 6, 6), this.warmMat);
450:       beacon.position.y = spire.position.y + spire.geometry.parameters.height / 2; g.add(beacon);
451:       this.animated.push({ type: 'beacon', mesh: beacon, phase: rng() * 6 });
