465:   buildDowntown(block, rng) {
466:     const { x, z } = block;
467:     const w = 34 + rng() * 26, d = 34 + rng() * 26;
468:     const h = 58 + rng() * 120;
469:     const offX = (rng() - .5) * (66 - w), offZ = (rng() - .5) * (66 - d);
470:     const bx = x + offX, bz = z + offZ;
471:     const variant = Math.floor(rng() * 4);
472:     const { mesh } = this.addBuilding(bx, bz, w, d, h, 'downtown', variant, { roofMat: this.roofMatDark });
473:     // podium
474:     const podH = 7 + rng() * 9;
475:     if (rng() > 0.35) {
476:       const pod = this.addBuilding(bx, bz, w + 8, d + 8, podH, 'downtown', (variant + 1) % 4, { roofMat: this.roofMat });
477:       pod.mesh.castShadow = true;
478:     }
479:     // setbacks
