481:       const h2 = h * (0.18 + rng() * .12);
482:       this.addBuilding(bx, bz, w * .72, d * .72, h2, 'downtown', (variant + 2) % 4, { base: h, roofMat: this.roofMatDark });
483:     }
484:     this.addRoofDetails(bx, bz, w, d, h + 0.2, rng, h > 70 ? 'tower' : 'normal');
485:     // facade fins for glass towers
486:     if (variant < 2) {
487:       const finMat = new THREE.MeshStandardMaterial({ color: 0x9fb3c4, roughness: .4, metalness: .6 });
488:       for (let i = -2; i <= 2; i++) {
489:         const fin = new THREE.Mesh(new THREE.BoxGeometry(0.28, h * .94, 0.5), finMat);
490:         fin.position.set(bx + i * w / 6, h / 2 + .2, bz + d / 2 + 0.3);
491:         this.root.add(fin);
492:       }
493:     }
494:     if (h > 125) {
