501:   buildMidrise(block, rng) {
502:     const { x, z } = block;
503:     const rows = rng() > .5 ? 2 : 1;
504:     for (let r = 0; r < rows; r++) {
505:       const w = 20 + rng() * 16, d = 18 + rng() * 14, h = 12 + rng() * 24;
