758:   buildSignals() {
759:     const nodes = [];
760:     for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
761:       const central = Math.abs(i - 4) <= 3 && Math.abs(j - 4) <= 3;
762:       nodes.push({ i, j, x: NODE_POS(i), z: NODE_POS(j), hasLights: central });
763:     }
764:     this.nodes = nodes;
765:     this.nodeGrid = [];
766:     for (let i = 0; i < GRID; i++) { this.nodeGrid[i] = []; for (let j = 0; j < GRID; j++) this.nodeGrid[i][j] = nodes.find(n => n.i === i && n.j === j); }
767: 
768:     const poleGeo = new THREE.CylinderGeometry(.12, .16, 4.8, 6);
769:     const poleMat = new THREE.MeshStandardMaterial({ color: 0x3a3f44, roughness: .8, metalness: .4 });
770:     const lampGeo = new THREE.SphereGeometry(.19, 8, 6);
771:     const lampMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
772:     const lampPositions = [];
773:     const poles = [];
774:     const armGeo = new THREE.BoxGeometry(2.2, .12, .12);
775:     const arms = [];
776:     this.signalLampData = [];
777:     for (const n of nodes) {
778:       if (!n.hasLights) continue;
779:       const corners = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
780:       for (const [sx, sz] of corners) {
781:         const px = n.x + sx * (HALF_ROAD + 1.3), pz = n.z + sz * (HALF_ROAD + 1.3);
782:         poles.push([px, 2.4, pz]);
783:         arms.push([px + (sx > 0 ? -1 : 1) * 1.1, 4.35, pz, sx > 0 ? 0 : Math.PI]);
784:         for (let k = 0; k < 3; k++) {
785:           const ly = 4.75 - k * .34;
786:           lampPositions.push([px + (sx > 0 ? -1.05 : 1.05), ly, pz]);
787:           this.signalLampData.push({ node: n, axis: sz === 0 ? 'x' : 'z', slot: k, index: lampPositions.length - 1 });
788:         }
789:       }
790:     }
791:     const poleMesh = new THREE.InstancedMesh(poleGeo, poleMat, poles.length);
792:     const tmp = new THREE.Object3D();
793:     poles.forEach(([x, y, z], i) => { tmp.position.set(x, y, z); tmp.updateMatrix(); poleMesh.setMatrixAt(i, tmp.matrix); });
794:     this.root.add(poleMesh);
795:     const armMesh = new THREE.InstancedMesh(armGeo, poleMat, arms.length);
796:     arms.forEach(([x, y, z, r], i) => { tmp.position.set(x, y, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix(); armMesh.setMatrixAt(i, tmp.matrix); });
797:     this.root.add(armMesh);
798:     this.signalLampMesh = new THREE.InstancedMesh(lampGeo, lampMat, lampPositions.length);
799:     this.signalLampMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(lampPositions.length * 3), 3);
800:     lampPositions.forEach(([x, y, z], i) => {
801:       tmp.position.set(x, y, z); tmp.rotation.set(0, 0, 0); tmp.updateMatrix();
802:       this.signalLampMesh.setMatrixAt(i, tmp.matrix);
803:       this.signalLampMesh.setColorAt(i, new THREE.Color(0x111111));
804:     });
805:     this.root.add(this.signalLampMesh);
806:     this.signalNodes = nodes;
807:   }
808: 
809:   signalState(node, axis, time) {
810:     if (!node.hasLights) return 'green';
811:     const t = (time + (node.i * 1.7 + node.j * 2.3)) % 26;
812:     if (axis === 'x') {
813:       if (t < 9) return 'green';
814:       if (t < 11) return 'yellow';
815:       return 'red';
816:     }
817:     if (t < 12) return 'red';
818:     if (t < 22) return 'green';
819:     if (t < 24) return 'yellow';
820:     return 'red';
821:   }
