823:   updateSignals(elapsed) {
824:     const colors = { red: new THREE.Color(0xff2b3e), yellow: new THREE.Color(0xffb12b), green: new THREE.Color(0x2bff9a), off: new THREE.Color(0x101316) };
825:     for (const data of this.signalLampData) {
826:       const state = this.signalState(data.node, data.axis, elapsed);
827:       const active = state === 'red' ? 0 : state === 'yellow' ? 1 : 2;
828:       let c;
829:       if (data.slot === active) c = colors[state];
830:       else c = colors.off;
831:       this.signalLampMesh.setColorAt(data.index, c);
832:     }
833:     this.signalLampMesh.instanceColor.needsUpdate = true;
834:   }
