840:         this.parkingSpots.push({ x: NODE_POS(i) + HALF_ROAD + 2.8, z: z1, heading: -Math.PI / 2 });
841:         this.parkingSpots.push({ x: NODE_POS(i) - HALF_ROAD - 2.8, z: z1, heading: Math.PI / 2 });
842:         const x1 = NODE_POS(j) + 18 + rng() * 50;
843:         this.parkingSpots.push({ x: x1, z: NODE_POS(i) + HALF_ROAD + 2.8, heading: Math.PI });
844:         this.parkingSpots.push({ x: x1, z: NODE_POS(i) - HALF_ROAD - 2.8, heading: 0 });
845:       }
846:     }
