849:   finalizeProps() {
850:     // instanced trees / benches accumulated during block generation
851:     if (this._trees && this._trees.length) {
852:       const n = this._trees.length;
853:       const trunk = new THREE.InstancedMesh(this._treeGeo.trunk, this._trunkMat, n);
854:       const leaves = new THREE.InstancedMesh(this._treeGeo.leaves, this._treeMat, n);
855:       const tmp = new THREE.Object3D();
856:       this._trees.forEach((t, i) => {
857:         tmp.position.set(t.x, 1.6 * t.scale + .15, t.z);
858:         tmp.scale.setScalar(t.scale); tmp.updateMatrix(); trunk.setMatrixAt(i, tmp.matrix);
