437: export function buildVehicleModel(type, color, opts = {}) {
438:   let v;
439:   if (['bus'].includes(type)) v = buildBus(color);
440:   else if (['truck', 'construction', 'fire', 'ambulance'].includes(type)) v = buildTruck(type, color);
441:   else if (type === 'motorcycle') v = buildMotorcycle(color);
442:   else if (type === 'boat') v = buildBoat(color);
443:   else if (type === 'helicopter') v = buildHelicopter(color);
444:   else v = buildCarLike(type, color);
445:   v.group.userData.vehicleType = type;
446:   v.group.userData.wheels = v.wheels;
447:   if (v.rider) v.group.userData.rider = v.rider;
448:   v.color = color;
449:   if (opts.traffic && v.rider) v.rider.visible = true;
450:   return v;
451: }
