import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.error('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') console.error('CONSOLE:', m.text()); });

await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.click('#btn-start');
await page.click('[data-start-mode="pc"]');
await page.waitForFunction(() => window.novaCity?.ready && window.novaCity.mode === 'playing', null, { timeout: 30000 });
await page.waitForTimeout(1800);
await page.screenshot({ path: join(out, 'test-start.png') });

const state = await page.evaluate(() => {
  const g = window.novaCity;
  const types = {};
  for (const v of g.vehicles.vehicles) types[v.type] = (types[v.type] || 0) + 1;
  return {
    mode: g.mode,
    player: { x: g.player.pos.x, z: g.player.pos.z, yaw: g.player.cameraYaw },
    traffic: g.vehicles.vehicles.length,
    types,
    islands: g.city.islands,
    bridges: g.city.bridges,
    airTraffic: g.city.airTraffic.length,
    airPositions: g.city.airTraffic.map(a => ({ x: +a.group.position.x.toFixed(1), y: +a.group.position.y.toFixed(1), z: +a.group.position.z.toFixed(1) })),
    monorail: g.city.monorail ? { progress: g.city.monorail.progress, stations: g.city.monorail.stations.length, station: g.city.monorail.currentStation } : null,
    rail: g.city.rail ? { progress: g.city.rail.progress, x: g.city.rail.group.position.x } : null,
    islandRail: g.city.islandRail ? { progress: g.city.islandRail.progress } : null,
    freight: !!g.city.freightRail,
    lighthouse: !!g.city.lighthouse,
    helipad: g.city.helipad ? { x: g.city.helipad.x, z: g.city.helipad.z } : null,
  };
});
console.log('STATE', JSON.stringify(state, null, 2));

// --- walking direction check: camera-relative D should move screen-right ---
const walk = await page.evaluate(async () => {
  const g = window.novaCity;
  const THREE = g.player.pos.constructor;
  g.player.setPosition(20, 120, .18); g.player.cameraYaw = Math.PI; g.player.heading = Math.PI;
