      this.speed = THREE.MathUtils.damp(this.speed, target, 1.4, dt);
      this.progress += this.speed * this.dir * dt;
      if (this.progress >= this.length - 2) { this.progress = this.length - 2; this.dir = -1; this.dwell = 6; this.speed = 0; }
