1361: function makePathAircraft(group, path, speed, opts = {}) {
1362:   const segments = [];
1363:   let total = 0;
1364:   for (let i = 0; i < path.length; i++) {
1365:     const a = path[i], b = path[(i + 1) % path.length];
1366:     const dx = b.x - a.x, dz = b.z - a.z, dy = b.y - a.y;
1367:     const len = Math.hypot(dx, dy, dz);
1368:     segments.push({ a, b, dx, dz, dy, len, heading: Math.atan2(dx, dz) });
1369:     total += len;
1370:   }
1371:   const air = {
1372:     group, path, segments, speed, total, distance: Math.random() * total,
1373:     heading: 0, bank: 0,
1374:     update(dt) {
1375:       this.distance = (this.distance + this.speed * dt) % this.total;
1376:       let d = this.distance, seg = this.segments[0];
1377:       for (const s of this.segments) {
1378:         if (d <= s.len) { seg = s; break; }
1379:         d -= s.len;
1380:       }
1381:       const t = seg.len > 0 ? d / seg.len : 0;
1382:       group.position.set(
1383:         seg.a.x + seg.dx * t,
1384:         seg.a.y + seg.dy * t,
1385:         seg.a.z + seg.dz * t
1386:       );
1387:       const horiz = Math.hypot(seg.dx, seg.dz);
1388:       if (horiz > .01) this.heading = Math.atan2(seg.dx, seg.dz);
1389:       const pitch = horiz > .01 ? -Math.atan2(seg.dy, horiz) * (opts.pitchScale ?? .5) : 0;
1390:       const turn = THREE.MathUtils.clamp(THREE.MathUtils.euclideanModulo(this.heading - group.rotation.y + Math.PI, TAU) - Math.PI, -.5, .5);
1391:       this.bank = THREE.MathUtils.damp(this.bank, -turn * (opts.bank ?? .4) * 6, 2.5, dt);
1392:       group.rotation.y = this.heading;
1393:       group.rotation.x = THREE.MathUtils.damp(group.rotation.x, THREE.MathUtils.clamp(pitch, -.22, .22), 2.5, dt);
1394:       group.rotation.z = this.bank;
1395:       if (this.rotor) { this.rotor.rotation.y += dt * 38; this.tailRotor.rotation.x += dt * 54; }
1396:     },
1397:   };
1398:   return air;
1399: }
