123:   const axles = allWheel ? [2, 2, 2] : [countFront, countRear];
124:   let idx = 0;
125:   for (let a = 0; a < zs.length; a++) {
126:     for (let side = -1; side <= 1; side += 2) {
127:       for (let d = 0; d < axles[a] / 2; d++) {
128:         const tire = addMesh(group, wheelGeo(wr, ww), tireMat, xs * side - side * d * ww * 1.1, wr, zs[a]);
129:         const rim = new THREE.Mesh(rimGeo(wr, ww), rimMat);
130:         rim.position.set(0, 0, 0); tire.add(rim);
131:         const hub = new THREE.Mesh(box(ww * 1.02, wr * 1.1, wr * 0.3), rimMat);
132:         hub.position.set(0, 0, 0); tire.add(hub);
133:         tire.userData.rim = rim;
134:         wheels.push({ mesh: tire, front: a === zs.length - 1, side });
135:         idx++;
